<template>
  <div class="wrong-center">
    <header class="page-header">
      <div>
        <div class="breadcrumb">学生学习 <span>/</span> 错题中心</div>
        <div class="title-row"><h1>错题中心</h1><span class="scope-chip">{{ currentStudent?.name || '当前学生' }}</span></div>
        <p>优先处理重复出错和还没有重练的题目</p>
      </div>
      <div class="header-actions">
        <el-button plain @click="$router.push('/')">返回工作台</el-button>
        <el-button type="primary" :disabled="!selectedQuestions.length" @click="createRetry">创建重练{{ selectedQuestions.length ? `（${selectedQuestions.length}）` : '' }}</el-button>
      </div>
    </header>

    <section class="context-bar">
      <button class="student-context" @click="showStudentDialog = true">
        <el-avatar :size="30" :src="currentStudent?.avatar">{{ currentStudent?.name?.slice(0, 1) || '?' }}</el-avatar>
        <span><b>{{ currentStudent?.name || '选择学生' }}</b><small>{{ currentStudent?.class || '暂无班级信息' }}</small></span><el-icon><ArrowDown /></el-icon>
      </button>
      <i class="divider" />
      <span class="context-stat">错题总数 <b>{{ stats.total }}</b></span><span class="context-stat danger">待处理 <b>{{ stats.pendingMaster }}</b></span><span class="context-stat success">已掌握 <b>{{ stats.mastered }}</b></span><span class="context-stat">掌握率 <b>{{ stats.masteryRate }}%</b></span>
      <span class="flex-spacer" /><el-button text @click="wrongBookStore.refreshData">刷新</el-button>
    </section>

    <main class="page-content">
      <section class="summary-strip"><button v-for="item in summaryItems" :key="item.key" :class="['summary-item', { active: activeSummary === item.key }]" @click="setSummary(item.key)"><span><i :class="['dot', item.tone]" />{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.note }}</small></button></section>
      <section class="toolbar">
        <label class="search"><el-icon><Search /></el-icon><input v-model="searchInput" placeholder="搜索题目、知识点" aria-label="搜索题目或知识点" @input="updateSearch" /></label>
        <el-select v-model="subjectFilter" size="small" placeholder="全部学科" @change="applySubject"><el-option label="全部学科" value="all" /><el-option v-for="subject in subjects" :key="subject" :label="subject" :value="subject" /></el-select>
        <el-select v-model="timeFilter" size="small" placeholder="全部时间" @change="applyTime"><el-option label="全部时间" value="all" /><el-option label="最近 7 天" value="week" /><el-option label="最近 30 天" value="month" /></el-select>
        <el-button size="small" plain @click="showAdvanced = !showAdvanced">更多筛选</el-button><span class="flex-spacer" /><small class="muted">{{ filteredQuestions.length }} 道题</small>
        <el-dropdown trigger="click" @command="handleSort"><el-button text size="small">{{ sortLabel }}⌄</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="priority">优先处理</el-dropdown-item><el-dropdown-item command="time_desc">最近新增</el-dropdown-item><el-dropdown-item command="error_desc">错误次数最多</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
      </section>
      <section v-if="showAdvanced" class="advanced"><span>问题类型</span><button v-for="item in categoryOptions" :key="item.key" :class="{ active: categoryFilter === item.key }" @click="applyCategory(item.key)">{{ item.label }}</button><el-button text size="small" @click="resetFilters">重置筛选</el-button></section>
      <section v-if="selectedQuestions.length" class="selection-bar"><el-checkbox :model-value="selectedQuestions.length === paginatedQuestions.length" @change="wrongBookStore.selectAll" /><b>已选择 {{ selectedQuestions.length }} 道题</b><span>可批量创建重练任务</span><span class="flex-spacer" /><el-button text size="small" @click="wrongBookStore.clearSelection">取消选择</el-button><el-button type="primary" size="small" @click="createRetry">创建重练</el-button></section>

      <section class="work-area">
        <div class="list-panel">
          <div class="list-head"><el-checkbox :model-value="paginatedQuestions.length > 0 && selectedQuestions.length === paginatedQuestions.length" @change="wrongBookStore.selectAll" /><b>{{ activeSummaryLabel }}</b><span>按优先级显示</span></div>
          <div v-loading="wrongBookStore.loading" class="question-list">
            <article v-for="question in paginatedQuestions" :key="question.id" :class="['question-row', { selected: selectedQuestion?.id === question.id }]" @click="selectedQuestion = question">
              <el-checkbox :model-value="isSelected(question)" @click.stop @change="() => wrongBookStore.toggleSelection(question)" />
              <div class="row-body"><div class="row-meta"><span class="subject">{{ subjectOf(question) }}</span><span>{{ question.grade || '题目' }}</span><time>{{ formatTime(question) }}</time></div><div class="row-title">{{ titleOf(question) || '暂无题目内容' }}</div><div class="row-meta"><span v-for="tag in tagsOf(question).slice(0, 2)" :key="tag" class="tag">{{ tag }}</span><span>·</span><span>错误 {{ question.error_count || 1 }} 次</span><span>·</span><span>重练 {{ question.practice_count || 0 }} 次</span></div></div>
              <span :class="['status', toneOf(question)]">{{ labelOf(question) }}</span><el-icon class="row-arrow"><ArrowRight /></el-icon>
            </article>
            <div v-if="!wrongBookStore.loading && !paginatedQuestions.length" class="empty"><el-icon><CircleCheck /></el-icon><b>没有符合条件的错题</b><span>试试清除筛选，或选择其他学生</span><el-button text type="primary" @click="resetFilters">清除筛选</el-button></div>
          </div><div class="pagination"><el-pagination v-model:current-page="currentPage" small layout="prev, pager, next" :page-size="PAGE_SIZE" :total="filteredQuestions.length" /></div>
        </div>

        <aside v-if="selectedQuestion" class="detail-panel"><div class="detail-head"><div><small>{{ subjectOf(selectedQuestion) }} · 学习记录</small><h2>{{ titleOf(selectedQuestion) || '暂无题目内容' }}</h2></div><el-button text circle @click="selectedQuestion = null">×</el-button></div><div class="detail-scroll"><div class="detail-status"><span :class="['status', toneOf(selectedQuestion)]">{{ labelOf(selectedQuestion) }}</span><span>最近错误 {{ formatTime(selectedQuestion) }}</span></div><section class="detail-block"><label>题目内容</label><p class="question-content">{{ contentOf(selectedQuestion) || '暂无题目内容' }}</p><img v-if="imageOf(selectedQuestion)" :src="imageOf(selectedQuestion)" alt="题目配图" /></section><section class="answer-grid detail-block"><div><label>学生答案</label><p class="wrong-answer">{{ answerOf(selectedQuestion, 'student_answer') || '未作答' }}</p></div><div><label>正确答案</label><p>{{ answerOf(selectedQuestion, 'answer') || '待补充' }}</p></div></section><section class="detail-block"><label>知识点</label><div><span v-for="tag in tagsOf(selectedQuestion)" :key="tag" class="tag">{{ tag }}</span><span v-if="!tagsOf(selectedQuestion).length" class="muted">尚未关联知识点</span></div></section><section class="detail-block"><div class="detail-line"><label>学习轨迹</label><small>错误 {{ selectedQuestion.error_count || 1 }} 次 · 重练 {{ selectedQuestion.practice_count || 0 }} 次</small></div><div class="timeline"><span><i class="timeline-dot danger" />最近一次答错 · {{ fullTime(selectedQuestion) }}</span><span><i class="timeline-dot neutral" />进入错题中心 · {{ fullTime(selectedQuestion) }}</span></div></section><section v-if="analysisOf(selectedQuestion)" class="detail-block"><label>解析</label><p class="analysis">{{ analysisOf(selectedQuestion) }}</p></section></div><div class="detail-actions"><el-button type="primary" @click="createRetryFor(selectedQuestion)">安排重练</el-button><el-button plain @click="markMastered(selectedQuestion)">标记已掌握</el-button><el-button plain @click="removeQuestion(selectedQuestion)">移除</el-button></div></aside>
        <aside v-else class="detail-placeholder"><el-icon><Reading /></el-icon><b>选择一道错题</b><span>查看题目证据、学习轨迹和下一步动作</span></aside>
      </section>
    </main>

    <el-dialog v-model="showStudentDialog" title="选择学生" width="420px" align-center><div class="student-picker"><button v-for="student in students" :key="student.id" :class="['student-option', { active: currentStudent?.id === student.id }]" @click="switchStudent(student)"><el-avatar :size="34" :src="student.avatar">{{ student.name?.slice(0, 1) }}</el-avatar><span><b>{{ student.name }}</b><small>{{ student.class || '暂无班级' }}</small></span><el-icon v-if="currentStudent?.id === student.id"><CircleCheck /></el-icon></button></div></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { ArrowDown, ArrowRight, CircleCheck, Reading, Search } from '@element-plus/icons-vue'
import { getStudents } from '../../services/apiService'
import { useWrongBookStore } from '../stores/wrongBookStore'
import dayjs from 'dayjs'

const wrongBookStore = useWrongBookStore(); const router = useRouter(); const route = useRoute(); const PAGE_SIZE = 17
const currentPage = computed({ get: () => wrongBookStore.currentPage, set: value => { wrongBookStore.currentPage = value } }); const currentStudent = computed(() => wrongBookStore.currentStudent); const selectedQuestions = computed(() => wrongBookStore.selectedQuestions); const filteredQuestions = computed(() => wrongBookStore.filteredQuestions); const paginatedQuestions = computed(() => wrongBookStore.paginatedQuestions); const stats = computed(() => wrongBookStore.stats); const subjects = computed(() => [...new Set(wrongBookStore.wrongQuestions.map(item => item.subject || item.question?.subject).filter(Boolean))]); const selectedQuestion = ref(null); const students = ref([]); const showStudentDialog = ref(false); const showAdvanced = ref(false); const activeSummary = ref('pending'); const searchInput = ref(wrongBookStore.searchQuery); const subjectFilter = ref(wrongBookStore.filters.subject || 'all'); const timeFilter = ref(wrongBookStore.filters.time || 'all'); const categoryFilter = ref(wrongBookStore.filters.category || 'all'); const sortLabel = ref('优先处理')
const categoryOptions = [{ key: 'all', label: '全部问题' }, { key: 'wrong', label: '答错' }, { key: 'unanswered', label: '未作答' }]; const summaryItems = computed(() => [{ key: 'pending', label: '待处理', value: stats.value.pendingMaster, note: '需要教师安排下一步', tone: 'danger' }, { key: 'repeat', label: '重复出错', value: wrongBookStore.wrongQuestions.filter(item => (item.error_count || 1) >= 2).length, note: '优先关注', tone: 'warning' }, { key: 'unpracticed', label: '尚未重练', value: wrongBookStore.wrongQuestions.filter(item => !(item.practice_count > 0)).length, note: '还没有后续练习', tone: 'info' }, { key: 'mastered', label: '已掌握', value: stats.value.mastered, note: '通过重练验证', tone: 'success' }]); const activeSummaryLabel = computed(() => summaryItems.value.find(item => item.key === activeSummary.value)?.label || '待处理')
const getQuestion = item => item?.question || item || {}; const titleOf = item => { const text = contentOf(item); return text.length > 72 ? `${text.slice(0, 72)}…` : text }; const contentOf = item => getQuestion(item).content || item?.content || ''; const subjectOf = item => item?.subject || getQuestion(item).subject || '未分类'; const tagsOf = item => { const q = getQuestion(item); return (q.tags_source === 'manual' ? q.manual_tags : (q.ai_tags || q.tags)) || [] }; const answerOf = (item, key) => getQuestion(item)[key] || item?.[key] || ''; const analysisOf = item => getQuestion(item).analysis || item?.analysis || ''; const imageOf = item => getQuestion(item).image_url || item?.question_image_url || ''; const formatTime = item => { const value = item?.added_at || item?.created_at; if (!value) return '-'; const date = dayjs(value); if (date.isSame(dayjs(), 'day')) return `今天 ${date.format('HH:mm')}`; if (date.isSame(dayjs().subtract(1, 'day'), 'day')) return `昨天 ${date.format('HH:mm')}`; return date.format('MM-DD HH:mm') }; const fullTime = item => item?.added_at ? dayjs(item.added_at).format('YYYY-MM-DD HH:mm') : '-'; const isSelected = item => selectedQuestions.value.some(selected => selected.id === item.id); const toneOf = item => item.lifecycle_status === 'mastered' || item.status === 'mastered' ? 'success' : (item.error_count >= 2 ? 'warning' : 'danger'); const labelOf = item => item.lifecycle_status === 'mastered' || item.status === 'mastered' ? '已掌握' : (item.error_count >= 2 ? '重复出错' : (item.practice_count > 0 ? '待重练' : '新错题'))
function updateSearch() { wrongBookStore.setSearchQuery(searchInput.value) }; function setSummary(key) { activeSummary.value = key; wrongBookStore.setFilter('status', key === 'mastered' ? 'mastered' : key === 'pending' ? 'pending' : 'all'); if (key === 'repeat') wrongBookStore.setFilter('errorCount', '2-3') }; function applySubject(value) { wrongBookStore.setFilter('subject', value || 'all') }; function applyTime(value) { wrongBookStore.setFilter('time', value || 'all') }; function applyCategory(value) { categoryFilter.value = value; wrongBookStore.setFilter('category', value) }; function resetFilters() { wrongBookStore.resetFilters(); activeSummary.value = 'pending'; subjectFilter.value = 'all'; timeFilter.value = 'all'; categoryFilter.value = 'all'; searchInput.value = ''; sortLabel.value = '优先处理' }; function handleSort(command) { sortLabel.value = command === 'time_desc' ? '最近新增' : command === 'error_desc' ? '错误次数最多' : '优先处理'; wrongBookStore.sortBy = command === 'priority' ? 'error_desc' : command }; function switchStudent(student) { wrongBookStore.setCurrentStudent(student); wrongBookStore.loadWrongQuestions(student.id); selectedQuestion.value = null; showStudentDialog.value = false }; function createRetry() { if (!selectedQuestions.value.length) { ElMessage.info('请先选择需要重练的题目'); return }; router.push({ path: '/exam-history', query: { studentId: currentStudent.value?.id } }) }; function createRetryFor(item) { wrongBookStore.clearSelection(); wrongBookStore.toggleSelection(item); createRetry() }; async function markMastered(item) { await wrongBookStore.updateLifecycleStatus(item.id, 'mastered'); ElMessage.success('已标记为已掌握') }; async function removeQuestion(item) { try { await ElMessageBox.confirm('移除后，这道题将不再出现在当前学生的错题列表中。', '移除错题', { confirmButtonText: '确认移除', cancelButtonText: '取消', type: 'warning' }); if (await wrongBookStore.deleteQuestion(item.id)) { selectedQuestion.value = null; ElMessage.success('错题已移除') } } catch {} }
onMounted(async () => { try { const result = await getStudents(false); students.value = result.data || result || []; const requestedStudentId = route.query.studentId; const requestedStudent = students.value.find(student => String(student.id) === String(requestedStudentId)); if (requestedStudent) switchStudent(requestedStudent); else if (students.value.length && !currentStudent.value) switchStudent(students.value[0]); else if (currentStudent.value) await wrongBookStore.loadWrongQuestions(currentStudent.value.id) } catch { ElMessage.error('学生列表加载失败，请刷新重试') } })
</script>

